<?php use App\Core\{Auth,DB}; ?><section class="panel"><h2>School users</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$users) emptyRow(5); foreach($users as $u): ?><tr><td><a href="<?= e(url('users',['edit'=>$u['id']])) ?>"><?= e($u['name']) ?></a></td><td><?= e($u['email']) ?></td><td><?= e($u['role_name']) ?></td><td><?php badge($u['active']?'Active':'Inactive'); ?></td><td><?php if($u['id']!==Auth::user()['id']): startForm('user.toggle',['id'=>$u['id']],'inline'); ?><button class="button" data-confirm="Change this user's access status?"><?= $u['active']?'Deactivate':'Activate' ?></button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><details class="panel" <?= !empty($editing)?'open':'' ?>><summary><?= !empty($editing)?'Edit user':'＋ Create a user' ?></summary><?php startForm('user.create',!empty($editing)?['id'=>$editing['id']]:[]); field('name','Full name','text',$editing['name']??''); field('email','Email','email',$editing['email']??''); field('password',!empty($editing)?'New password · leave blank to retain':'Initial password · at least 12 characters','password','',empty($editing)); selectField('role_id','Role','roles',$editing['role_id']??''); selectField('student_id','Linked student · required for student access','students',$editing['student_id']??'',false); endForm(!empty($editing)?'Save user':'Create user'); ?></details><details class="panel"><summary>Roles & permissions</summary><p class="muted">Permissions are enforced on the server. Changes take effect on the next request. Your current role cannot be edited from this account.</p><?php foreach($roles as $role): $codes=array_column(DB::all('SELECT p.code FROM permissions p JOIN role_permissions rp ON rp.permission_id=p.id WHERE rp.role_id=?',[$role['id']]),'code'); ?><details class="role-block"><summary><?= e($role['name']) ?></summary><?php if((int)$role['id']===(int)Auth::user()['role_id']): ?><p>Use a different administrator role to edit this role.</p><?php else: startForm('role.permissions',['role_id'=>$role['id']]); foreach(App\Services\Schools::PERMISSIONS as $code): ?><label class="check"><input type="checkbox" name="permissions[]" value="<?= e($code) ?>" <?= in_array($code,$codes,true)?'checked':'' ?>><?= e($code) ?></label><?php endforeach; endForm('Save permissions'); endif ?></details><?php endforeach; startForm('role.create'); field('name','New role name'); endForm('Create role'); ?></details>
